//==========================================
// TUI MODULE (text user interface)
// Colors (ANSI escape codes), aligned tables, banners and boxes.
// No extra library is needed, everything is plain text.
//
// Colors are only turned on when the program runs in a real terminal.
// They stay OFF when the output is redirected to a file, when the user starts the
// program with --plain, or when the NO_COLOR environment variable is set.
// Only ASCII characters are used for the borders, so every console shows them correctly.
//==========================================

bool tuiColor = false;

const char* const C_RESET   = "\033[0m";
const char* const C_BOLD    = "\033[1m";
const char* const C_DIM     = "\033[2m";
const char* const C_RED     = "\033[31m";
const char* const C_GREEN   = "\033[32m";
const char* const C_YELLOW  = "\033[33m";
const char* const C_BLUE    = "\033[34m";
const char* const C_MAGENTA = "\033[35m";
const char* const C_CYAN    = "\033[36m";
const char* const C_TITLE   = "\033[1;36m";    // bold cyan

const size_t TUI_WIDTH = 79;

// call once at the start. force = true keeps the colors even when the output is not a terminal
//--- tuiInit --------------------------------------------------------------------------------------
// What    : Decides once at the start whether ANSI colors are used: off for --plain, off when
//           NO_COLOR is set, on only for a real terminal unless forced. On Windows it also enables
//           ANSI processing.
// Used by : main (main.cpp)
//--------------------------------------------------------------------------------------------------
void tuiInit(bool allowColor, bool force = false) {
    tuiColor = false;
    if (!allowColor) return;
    if (std::getenv("NO_COLOR") != nullptr) return;
#ifdef _WIN32
    HANDLE out = GetStdHandle(STD_OUTPUT_HANDLE);
    DWORD mode = 0;
    if (out == INVALID_HANDLE_VALUE || !GetConsoleMode(out, &mode)) { tuiColor = force; return; }
    // Windows 10+ needs "virtual terminal processing" to understand ANSI colors
    tuiColor = SetConsoleMode(out, mode | 0x0004) != 0 || force;
#else
    tuiColor = force || (isatty(STDOUT_FILENO) != 0);
#endif
}

// colored text (plain text when colors are off)
//--- paint ----------------------------------------------------------------------------------------
// What    : Wraps a text in a color code. Returns the plain text when colors are off.
// Returns : the colored text
// Used by : doSortFilter (store.h), printGameRow (store.h), printGameTable (store.h),
//           printTableHeader (store.h), showGamePage (store.h), showMyGames (store.h),
//           showStorePage (store.h), showTagIndex (store.h), tagChips, tuiBanner, tuiMenu, tuiRule,
//           tuiSection
//--------------------------------------------------------------------------------------------------
std::string paint(const std::string& text, const char* color) {
    if (!tuiColor) return text;
    return std::string(color) + text + C_RESET;
}

//==========================
// layout helpers. ALWAYS pad first and paint after, because the color codes have no width
//==========================
//--- repeatChar -----------------------------------------------------------------------------------
// What    : A text made of one character repeated n times (used for borders).
// Returns : the text
// Used by : tableRule (store.h), tuiBanner, tuiRule, tuiSection
//--------------------------------------------------------------------------------------------------
std::string repeatChar(char c, size_t n) {
    return std::string(n, c);
}

// cut long text with "..." and pad short text with spaces to exactly 'width' characters
//--- fit ------------------------------------------------------------------------------------------
// What    : Cuts a text with "..." or pads it with spaces to exactly the width. Counts characters,
//           not bytes, so accents do not break the table.
// Returns : a text of exactly width characters
// Used by : doShowcase (screens.h), printGameRow (store.h), printTableHeader (store.h), tuiMenu
//--------------------------------------------------------------------------------------------------
std::string fit(const std::string& s, size_t width) {
    std::string out = s;
    if (utf8Length(out) > width) {
        if (width > 3) out = utf8Prefix(out, width - 3) + "...";
        else out = utf8Prefix(out, width);
    }
    size_t shown = utf8Length(out);
    out.append(width - shown, ' ');
    return out;
}

// right aligned, cut to the width when too long (counts characters, not bytes)
//--- fitRight -------------------------------------------------------------------------------------
// What    : Right aligned version of fit (used for numbers).
// Returns : a text of exactly width characters
// Used by : printGameRow (store.h), printTableHeader (store.h), tuiMenu
//--------------------------------------------------------------------------------------------------
std::string fitRight(const std::string& s, size_t width) {
    std::string out = utf8Prefix(s, width);
    return std::string(width - utf8Length(out), ' ') + out;
}

// centered inside the width (counts characters, not bytes)
//--- centerText -----------------------------------------------------------------------------------
// What    : Centers a text inside a width (used by the banner).
// Returns : a text of exactly width characters
// Used by : tuiBanner
//--------------------------------------------------------------------------------------------------
std::string centerText(const std::string& s, size_t width) {
    size_t len = utf8Length(s);
    if (len >= width) return utf8Prefix(s, width);
    size_t left = (width - len) / 2;
    return std::string(left, ' ') + s + std::string(width - len - left, ' ');
}

//==========================
// banner and section headers
//==========================
//--- tuiBanner ------------------------------------------------------------------------------------
// What    : Prints the big boxed title of the store page.
// Used by : showStorePage (store.h)
//--------------------------------------------------------------------------------------------------
void tuiBanner(const std::string& title) {
    std::string line = "+" + repeatChar('-', TUI_WIDTH - 2) + "+";
    std::cout << "\n" << paint(line, C_TITLE) << "\n"
              << paint("|" + centerText(title, TUI_WIDTH - 2) + "|", C_TITLE) << "\n"
              << paint(line, C_TITLE) << "\n";
}

//--- tuiSection -----------------------------------------------------------------------------------
// What    : Prints a section title line such as == CART ===== that fills the screen width.
// Used by : doBundle (screens.h), doDiscover (screens.h), doDownloads (screens.h), doFeatured
//           (screens.h), doGenres (screens.h), doHistory (screens.h), doLab (screens.h), doLogin
//           (store.h), doNetwork (screens.h), doPublish (store.h), doRecent (screens.h), doRegister
//           (store.h), doSearch (store.h), doShowcase (screens.h), doSortFilter (store.h), doStudio
//           (store.h), lessonStep (screens.h), showGamePage (store.h)
//--------------------------------------------------------------------------------------------------
void tuiSection(const std::string& title) {
    std::string text = "== " + title + " ";
    if (text.size() < TUI_WIDTH) text += repeatChar('=', TUI_WIDTH - text.size());
    std::cout << "\n" << paint(text, C_TITLE) << "\n";
}

//--- tuiRule --------------------------------------------------------------------------------------
// What    : Prints a plain horizontal line.
// Used by : showGamePage (store.h), showStorePage (store.h)
//--------------------------------------------------------------------------------------------------
void tuiRule() {
    std::cout << paint(repeatChar('-', TUI_WIDTH), C_DIM) << "\n";
}

// "[tag1] [tag2]" in color
//--- tagChips -------------------------------------------------------------------------------------
// What    : Shows tags as [action] [co-op], colored when colors are on.
// Returns : the text
// Used by : doSortFilter (store.h), showGamePage (store.h), showMyGames (store.h), showStorePage
//           (store.h)
//--------------------------------------------------------------------------------------------------
std::string tagChips(const std::vector<std::string>& tags) {
    std::string out;
    for (size_t i = 0; i < tags.size(); i++) {
        if (i > 0) out += " ";
        out += paint("[" + tags[i] + "]", C_MAGENTA);
    }
    return out;
}

//==========================
// numbered menu, two columns
//==========================
//--- tuiMenu --------------------------------------------------------------------------------------
// What    : Prints a numbered menu in two columns (entries 1..n, then 0 for the exit or back
//           entry).
// Used by : handleMenu (store.h)
//--------------------------------------------------------------------------------------------------
void tuiMenu(const std::vector<std::string>& labels, const std::string& zeroLabel) {
    std::vector<std::string> cells;
    for (size_t i = 0; i < labels.size(); i++) {
        std::string num = fitRight(std::to_string(i + 1), 2);
        cells.push_back(num + ") " + labels[i]);
    }
    cells.push_back(" 0) " + zeroLabel);

    const size_t colWidth = 36;
    std::cout << "\n";
    for (size_t i = 0; i < cells.size(); i += 2) {
        // color only the "NN)" part of each cell
        std::string left = cells[i];
        std::string leftNum = left.substr(0, 3);
        std::cout << "  " << paint(leftNum, C_YELLOW) << fit(left.substr(3), colWidth);
        if (i + 1 < cells.size()) {
            std::string right = cells[i + 1];
            std::cout << paint(right.substr(0, 3), C_YELLOW) << right.substr(3);
        }
        std::cout << "\n";
    }
}

// a text progress bar: [#########-----------]  value out of total, width characters wide
//--- progressBar ----------------------------------------------------------------------------------
// What    : Draws a progress bar like [#####-----] for the download screen.
// Returns : the bar text
// Used by : doDownloads (screens.h), doShowcase (screens.h)
//--------------------------------------------------------------------------------------------------
std::string progressBar(int value, int total, int width) {
    if (total <= 0) total = 1;
    if (value < 0) value = 0;
    if (value > total) value = total;
    int filled = (int)((long long)value * width / total);
    return "[" + std::string((size_t)filled, '#') + std::string((size_t)(width - filled), '-') + "]";
}

#endif //STEAM_TUI_H
